```json
{
  "root_causes": [
    {
      "service": "ts-train-food-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) AS n, quantile_cont(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name = 'ts-train-food-service' GROUP BY 1,2,3 ORDER BY p95_ms DESC LIMIT 5", "claim": "TrainFoodController.getTrainFoodOfTrip p95 is about 1376 ms while its repository and SQL child spans stay around 0.3 to 2.7 ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) AS n, quantile_cont(duration,0.95)/1e6 AS p95_ms FROM normal_traces WHERE service_name = 'ts-train-food-service' AND attr_span_kind = 'Internal' AND span_name LIKE 'TrainFoodController%' GROUP BY 1,2,3", "claim": "Baseline comparison for the train-food controller method span in the normal period, before the incident."},
        {"kind": "metric", "sql": "SELECT metric, AVG(value) AS avg_v, MAX(value) AS max_v FROM abnormal_metrics WHERE service_name = 'ts-train-food-service' AND metric IN ('container.cpu.usage','container.memory.working_set','k8s.container.restarts') GROUP BY 1", "claim": "Train-food container CPU and memory stay at or below normal levels, with no restarts, so the slowness is not resource saturation."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-food-service",
      "to": "ts-food-service",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) AS n, quantile_cont(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name = 'ts-food-service' AND attr_span_kind IN ('Server','Client') GROUP BY 1,2,3 ORDER BY p95_ms DESC", "claim": "Food-service GET spans to train-food rose to p95 about 1377 ms, and its own server span for foods rose to about 1399 ms."}
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) AS n, quantile_cont(duration,0.95)/1e6 AS p95_ms FROM abnormal_traces WHERE service_name = 'ts-ui-dashboard' AND span_name LIKE '%foodservice/foods%' GROUP BY 1,2,3", "claim": "User-facing dashboard food endpoint p95 rose to about 1400 ms from about 30 ms in the normal period."}
      ]
    }
  ]
}
```

